 "Les provisions sont indicatives. « Marquer payée » associe une dépense déjà saisie ou importée ; aucun paiement ni nouvelle dépense n’est créé. Un paiement peut être rapproché d’une échéance d’un autre mois.": {
  "en": "Provisions are indicative. “Mark as paid” links an existing expense; no payment or new expense is created. A payment may be matched to a due date in another month.",
  "ar": "المخصصات تقديرية. يربط «تحديد كمدفوعة» نفقة مسجلة أو مستوردة، دون إنشاء دفعة أو نفقة جديدة. يمكن مطابقة دفعة مع استحقاق من شهر آخر."
 },
 "Partage du foyer": {
  "en": "Household sharing",
  "ar": "مشاركة الأسرة"
 },
 "Ajoutez un adulte au budget «": {
  "en": "Add an adult to the budget “",
  "ar": "أضف شخصًا بالغًا إلى ميزانية «"
 },
 "». Si cette personne possède déjà un foyer, il reste intact : elle pourra passer de l’un à l’autre avec l’icône du foyer.": {
  "en": "”. If they already have a household, it remains intact: they can switch between households using the household icon.",
  "ar": "». إذا كان لديه أسرة في التطبيق، فستبقى كما هي ويمكنه التبديل بين الأسر عبر أيقونة الأسرة."
 },
 "Seul le propriétaire du foyer peut créer des invitations ou gérer les accès.": {
  "en": "Only the household owner can create invitations or manage access.",
  "ar": "مالك الأسرة وحده يستطيع إنشاء الدعوات أو إدارة الوصول."
 },
 "Avec une adresse, seul ce compte peut accepter. Sans adresse, toute personne connectée qui reçoit le lien peut rejoindre ce foyer. L’acceptation ne fusionne pas les foyers existants.": {
  "en": "With an email address, only that account can accept. Without one, any signed-in recipient can join. Accepting does not merge existing households.",
  "ar": "عند تحديد بريد إلكتروني، يستطيع ذلك الحساب وحده القبول. دونه، يمكن لأي مستلم مسجل الدخول الانضمام. لا يؤدي القبول إلى دمج الأسر الموجودة."
 },
 "Votre lien d’invitation": {
  "en": "Your invitation link",
  "ar": "رابط دعوتك"
 },
