 "Suggestions automatiques": {
  "en": "Automatic suggestions",
  "ar": "اقتراحات تلقائية"
 },
 "Pour les opérations encore à classer, Horizon combine vos règles, son dictionnaire de commerçants et ce qu’il apprend de vos opérations déjà classées. Tout est calculé sur votre appareil, gratuitement. Vous choisissez ce qui est appliqué.": {
  "en": "For transactions still to be categorised, Horizon combines your rules, its merchant dictionary and what it learns from your already categorised transactions. Everything is calculated on your device, for free. You choose what gets applied.",
  "ar": "بالنسبة إلى المعاملات التي لم تُصنَّف بعد، يجمع Horizon بين قواعدك وقاموس التجار الخاص به وما يتعلمه من معاملاتك المصنفة سابقا. كل شيء يُحسب على جهازك مجانا. أنت من يختار ما يُطبَّق."
 },
