 "Règles de catégorisation du foyer": {
  "en": "Household categorisation rules",
  "ar": "قواعد تصنيف الأسرة"
 },
 "Quand le libellé d’une opération contient l’expression d’une règle, Horizon propose sa catégorie et sa nature. La règle la plus précise l’emporte, et les règles du foyer passent avant le dictionnaire général.": {
  "en": "When a transaction’s description contains a rule’s phrase, Horizon suggests its category and type. The most specific rule wins, and household rules take priority over the general dictionary.",
  "ar": "عندما يحتوي وصف المعاملة على عبارة قاعدة ما، يقترح Horizon فئتها ونوعها. تسود القاعدة الأكثر دقة، وتتقدم قواعد الأسرة على القاموس العام."
 },
